using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Web.Script.Serialization;

namespace PZ3D {
 static class LauncherJournalIOTests {
  static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=4194304};
  static readonly List<string> Failures=new List<string>();static int checks;
  static void Check(bool value,string name){checks++;if(!value)throw new Exception(name);}
  static Dictionary<string,object> P(params object[] fields){var value=new Dictionary<string,object>();for(int i=0;i<fields.Length;i+=2)value[(string)fields[i]]=fields[i+1];return value;}
  static Dictionary<string,object> D(object value){return Json.Deserialize<Dictionary<string,object>>(Json.Serialize(value));}
  static Dictionary<string,object>[] Rows(Dictionary<string,object> value){return ((IEnumerable)value["history"]).Cast<Dictionary<string,object>>().ToArray();}
  static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","");}
  static void Put(string file,string text){Directory.CreateDirectory(Path.GetDirectoryName(file));File.WriteAllText(file,text,new UTF8Encoding(false));}
  sealed class Fixture:IDisposable {
   internal readonly string Root,Game,User,Data,Save,Backups,Tasks;internal readonly ModernController Controller;
   readonly ModernDispatchQueue queue=new ModernDispatchQueue();readonly Dictionary<string,string> hashes;readonly Dictionary<string,long> times;
   internal Fixture(string parent,string name){Root=Path.Combine(parent,name+"-"+Guid.NewGuid().ToString("N").Substring(0,8));Game=Path.Combine(Root,"g");User=Path.Combine(Root,"u");Data=Path.Combine(Root,"d");Save=Path.Combine(User,"Saves","Sandbox","Fixture");Backups=Path.Combine(Root,"b");Tasks=Path.Combine(Data,"diagnostics","tasks.json");Put(Path.Combine(Game,"ProjectZomboid64.exe"),"OWNED DUMMY; NEVER EXECUTE");Put(Path.Combine(Game,"ProjectZomboid64.json"),"{\"vmArgs\":[]}");Put(Path.Combine(Game,"version.txt"),"42.21");Put(Path.Combine(User,"mods","default.txt"),"mods\n{\n}\n");Put(Path.Combine(Save,"mods.txt"),"mods\n{\n}\n");Put(Path.Combine(Save,"map.bin"),"small-journal-io-fixture");var files=Directory.GetFiles(Game,"*",SearchOption.AllDirectories).Concat(Directory.GetFiles(User,"*",SearchOption.AllDirectories)).ToArray();hashes=files.ToDictionary(p=>p,p=>Hash(File.ReadAllBytes(p)));times=files.ToDictionary(p=>p,p=>File.GetLastWriteTimeUtc(p).Ticks);Controller=new ModernController(Game,User,Data,false);Request("launchConfigurationSelect",P("id","steam"));Request("backupSettingsSave",P("directory",Backups,"retention",10,"afterExit",false));}
   internal object Request(string action,Dictionary<string,object> payload=null){payload=payload??P();var captured=Controller.CaptureRequest(action,payload);return (ModernController.ConfigurationMutation(action,payload)?queue.ExecuteConcurrentMutation(captured):queue.ExecuteSnapshot(captured)).GetAwaiter().GetResult();}
   internal object Backup(string label){return Request("backupCreate",P("id","Sandbox/Fixture","label",label));}
   internal FileStream HoldTasks(){return new FileStream(Tasks,FileMode.Open,FileAccess.Read,FileShare.ReadWrite);}
   internal Dictionary<string,object> Snapshot(){return D(Request("taskGet"));}
   internal void PendingSnapshot(string expected){var snapshot=Snapshot();Check(Rows(snapshot).Any(r=>(string)r["action"]=="backupCreate"&&(string)r["status"]==expected),"same controller exposes actual "+expected+" state despite journal write failure");Check(!Rows(snapshot).Any(r=>(string)r["status"]=="running"),"same controller has no stale running history");Check(snapshot.ContainsKey("persistenceWarning")&&!string.IsNullOrWhiteSpace(Convert.ToString(snapshot["persistenceWarning"])),"journal persistence warning is explicit");using(var reader=new ModernController(Game,User,Data,false,null,null,null,null,true,null,true)){var view=D(reader.CaptureRequest("taskGet",P())());Check(Rows(view).Any(r=>(string)r["action"]=="backupCreate"&&(string)r["status"]==expected)&&!Rows(view).Any(r=>(string)r["status"]=="running"),"new readonly controller shares pending terminal history");Check(view.ContainsKey("persistenceWarning")&&!string.IsNullOrWhiteSpace(Convert.ToString(view["persistenceWarning"])),"new readonly controller sees persistence warning");}}
   internal void SourcesUnchanged(){Check(hashes.All(p=>Hash(File.ReadAllBytes(p.Key))==p.Value&&File.GetLastWriteTimeUtc(p.Key).Ticks==times[p.Key]),"all owned source hashes and mtimes are unchanged");}
   internal void Zips(int count){var files=Directory.Exists(Backups)?Directory.GetFiles(Backups,"*.zip",SearchOption.AllDirectories):new string[0];Check(files.Length==count,"actual published ZIP count is "+count);foreach(var file in files)using(var zip=ZipFile.OpenRead(file)){var entries=zip.Entries.Where(e=>e.FullName.StartsWith("world/")&&!e.FullName.EndsWith("/")).ToArray();Check(entries.Length==2,"actual ZIP contains exactly both save files");foreach(var e in entries)using(var input=e.Open())using(var output=new MemoryStream()){input.CopyTo(output);Check(Hash(output.ToArray())==Hash(File.ReadAllBytes(Path.Combine(Save,e.FullName.Substring(6)))),"actual ZIP entry hash matches source "+e.FullName);}}Check(!Directory.GetFiles(Root,"*.new-*",SearchOption.AllDirectories).Any()&&!Directory.GetFiles(Root,".creating-*",SearchOption.AllDirectories).Any(),"no unpublished state or ZIP temporary files remain");}
   internal void Persisted(string[] expected){var store=LauncherNativeState.Read(Tasks,()=>new LauncherTaskStore());foreach(string status in expected)Check(store.history.Count(r=>r.action=="backupCreate"&&r.status==status)>=expected.Count(s=>s==status),"after unlock actual disk retains all "+status+" tasks");Check(!store.history.Any(r=>r.status=="running"),"after unlock disk has no stale running task");var snapshot=Snapshot();Check(snapshot.ContainsKey("persistenceWarning")&&string.IsNullOrEmpty(Convert.ToString(snapshot["persistenceWarning"])),"persistence warning clears after successful flush");}
   public void Dispose(){Controller.Dispose();string full=Path.GetFullPath(Root),parent=Path.GetFullPath(Path.GetDirectoryName(Root))+Path.DirectorySeparatorChar;if(!full.StartsWith(parent,StringComparison.OrdinalIgnoreCase))throw new Exception("fixture cleanup escaped owner");if(Directory.Exists(full))Directory.Delete(full,true);}
  }
  static void Healthy(string root){using(var f=new Fixture(root,"healthy")){int progress=0;f.Controller.Progress=(value,text)=>progress++;using(f.HoldTasks()){f.Backup("held-healthy");Check(progress>0,"real progress continues while journal cannot persist");f.Zips(1);f.SourcesUnchanged();f.PendingSnapshot("completed");}f.Backup("flush-healthy");f.Zips(2);f.Persisted(new[]{"completed","completed"});f.SourcesUnchanged();}}
  static void Cancellation(string root){using(var f=new Fixture(root,"cancel")){bool cancelled=false,requested=false;f.Controller.Progress=(value,text)=>{if(!requested&&text.StartsWith("扫描存档：")){requested=true;f.Controller.Cancel();}};using(f.HoldTasks()){try{f.Backup("held-cancel");}catch(OperationCanceledException){cancelled=true;}Check(requested&&cancelled,"real cancellation remains OperationCanceledException while journal cannot persist");Check(!f.Controller.Busy,"cancel releases native busy state");f.Zips(0);f.PendingSnapshot("cancelled");}f.Controller.Progress=null;f.Backup("cancel-retry");f.Zips(1);f.Persisted(new[]{"completed","cancelled"});f.SourcesUnchanged();}}
  static void OriginalError(string root){using(var f=new Fixture(root,"original")){var sentinel=new InvalidDataException("AUDIT_ORIGINAL_CALLBACK_SENTINEL");Exception caught=null;bool fired=false;FileStream held=null;f.Controller.Progress=(value,text)=>{if(!fired&&text.StartsWith("扫描存档：")){fired=true;held=f.HoldTasks();throw sentinel;}};try{try{f.Backup("held-original");}catch(Exception e){caught=e;}Check(fired&&Object.ReferenceEquals(caught,sentinel),"journal Finish cannot replace original callback exception");Check(!f.Controller.Busy,"original error releases native busy state");f.Zips(0);f.PendingSnapshot("failed");}finally{if(held!=null)held.Dispose();}f.Controller.Progress=null;f.Backup("original-retry");f.Zips(1);f.Persisted(new[]{"completed","failed"});f.SourcesUnchanged();}}
  static void LogOnly(string root){using(var f=new Fixture(root,"log")){string log=Path.Combine(f.Data,"diagnostics","launcher.log");int progress=0;f.Controller.Progress=(value,text)=>progress++;using(var held=new FileStream(log,FileMode.Open,FileAccess.Read,FileShare.Read)){f.Backup("held-log-only");Check(progress>0,"append failure does not stop real progress");f.Zips(1);f.PendingSnapshot("completed");f.SourcesUnchanged();}f.Backup("flush-log-only");f.Zips(2);f.Persisted(new[]{"completed","completed"});f.SourcesUnchanged();}}
  static void ImmutableSnapshot(string root){using(var f=new Fixture(root,"snapshot")){using(f.HoldTasks()){var journal=new LauncherJournal(f.Data);string id=journal.Begin("probe","immutable snapshot");journal.Update(-1,"before");object before=journal.Snapshot();string serialized=Json.Serialize(before);journal.Update(35,"after");journal.Finish("completed","done");Check(Json.Serialize(before)==serialized,"a pending snapshot does not change after subsequent Update and Finish");var old=Rows(D(before)).Single(r=>(string)r["id"]==id);Check((string)old["status"]=="running"&&(int)old["progress"]==-1&&((IEnumerable)old["events"]).Cast<object>().Count()==1,"old snapshot retains captured state, progress and event count");var current=Rows(D(journal.Snapshot())).Single(r=>(string)r["id"]==id);Check((string)current["status"]=="completed"&&(int)current["progress"]==100,"new snapshot reflects authoritative terminal state");}f.SourcesUnchanged();}}
  static void Run(string name,Action action){try{action();Console.WriteLine("PASS "+name);}catch(Exception e){Failures.Add(name+": "+e.Message);Console.WriteLine("FAIL "+name+"\n"+e);}}
  public static int Main(string[] args){Console.OutputEncoding=new UTF8Encoding(false);Console.Error.WriteLine("Headless native journal regression; dummy game files are never executed.");string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);LauncherRuntime.Initialize();Run("healthy real backup despite unavailable journal",()=>Healthy(root));Run("real cancellation despite unavailable journal",()=>Cancellation(root));Run("original exception despite unavailable journal",()=>OriginalError(root));Run("append-only IO failure",()=>LogOnly(root));Run("immutable pending snapshot",()=>ImmutableSnapshot(root));Console.WriteLine(Json.Serialize(new{checks,failures=Failures,scope="Production ModernController TestMode=false and actual host dispatch; isolated two-file saves/dummy game never executed; real held tasks handle; no UI/game acceptance."}));return Failures.Count==0?0:1;}
 }
}
